14	}
15	
16	@Component({
17	  selector: 'app-sitzplatzwahl',
18	  imports: [FormsModule, RouterLink, SitzplanComponent, DecimalPipe],
19	  templateUrl: './sitzplatzwahl.html',
20	  styleUrl: './sitzplatzwahl.scss'
21	})
22	export class SitzplatzwahlComponent {
23	  private readonly route = inject(ActivatedRoute);
24	  private readonly router = inject(Router);
25	  private readonly veranstaltungenService = inject(VeranstaltungenService);
26	  private readonly buchungenService = inject(BuchungenService);
27	
28	  protected readonly veranstaltungId = this.route.snapshot.paramMap.get('id')!;
29	  protected readonly veranstaltung = signal<VeranstaltungDetail | null>(null);
30	  protected readonly sitzplan = signal<Sitzplan | null>(null);
31	  protected readonly ausgewaehlteSitzplaetze = signal<AusgewaehlterSitzplatz[]>([]);
32	  protected readonly ladeFehler = signal<string | null>(null);
33	  protected readonly buchungFehler = signal<string | null>(null);
34	  protected readonly wirdGebucht = signal(false);
35	
36	  protected readonly ausgewaehltePositionen = computed<SitzplatzPosition[]>(() =>
37	    this.ausgewaehlteSitzplaetze().map(({ reihe, spalte }) => ({ reihe, spalte }))
38	  );
39	
40	  protected readonly gesamtpreis = computed(() => {
41	    const veranstaltung = this.veranstaltung();
42	    if (!veranstaltung) {
43	      return 0;
44	    }
45	    return this.ausgewaehlteSitzplaetze().reduce((summe, sitzplatz) => {
46	      const kategorie = veranstaltung.preiskategorien.find((k) => k.id === sitzplatz.preiskategorieId);
47	      return summe + (kategorie?.preis ?? 0);
48	    }, 0);
49	  });
50	
51	  protected name = '';
52	  protected email = '';
53	
